// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {BridgeAdapter} from "./BridgeAdapter.sol";
import {TokenDecimals} from "../libraries/TokenDecimals.sol";
import {BridgeExecution, BridgeFee, BridgeQuote} from "../interfaces/IBridgeAdapter.sol";
import {ILayerZeroOft, LayerZeroMessagingFee, LayerZeroSendParam} from "../interfaces/ILayerZeroOft.sol";
import {IOVaultComposerSync} from "../interfaces/IOVaultComposerSync.sol";

/// @title OVaultComposerAdapter
/// @author Agustin Aguilar
/// @notice Adapter for hub-chain OVault deposits bridged to another chain as vault-share OFTs
contract OVaultComposerAdapter is BridgeAdapter, Ownable {
  struct Destination {
    address composer;
    address tokenOut;
    uint32 dstEid;
    uint8 shareDecimals;
    uint8 tokenOutDecimals;
    uint256 shareConversionRate;
    bytes extraOptions;
  }

  struct TransferReceipt {
    uint256 amountIn;
    uint256 amountOut;
    uint256 nativeFee;
    uint32 dstEid;
    bytes32 recipient;
  }

  struct OVaultQuote {
    BridgeQuote bridgeQuote;
    IOVaultComposerSync composer;
    LayerZeroSendParam sendParam;
    LayerZeroMessagingFee fee;
  }

  uint256 public nextOperationNonce;

  mapping(address tokenIn => mapping(uint256 dstChainId => Destination destination)) public destinations;

  event DestinationSet(
    address indexed _tokenIn,
    uint256 indexed _dstChainId,
    address indexed _tokenOut,
    address _composer,
    uint32 _dstEid,
    uint8 _shareDecimals,
    uint8 _tokenOutDecimals,
    bytes _extraOptions
  );
  event DestinationCleared(address indexed _tokenIn, uint256 indexed _dstChainId);
  event OVaultDepositAndBridgeStarted(
    bytes32 indexed _operationId,
    address indexed _inbox,
    address indexed _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _amountOut,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    uint256 _nativeFee,
    uint32 _dstEid
  );

  error ZeroAddress();
  error InvalidAmount();
  error InvalidRecipient();
  error InvalidOptions();
  error UnsupportedDestination(address _tokenIn, uint256 _dstChainId);
  error InvalidBridgeToken(address _expected, address _actual);
  error InvalidTokenOut(address _expected, address _actual);
  error InsufficientAmountOut(uint256 _expected, uint256 _actual);
  error InvalidTokenOutDecimals(uint8 _tokenOutDecimals, uint8 _sharedDecimals);

  constructor(address _owner) Ownable(_owner) {}

  /// @notice Sets destination metadata for the LayerZero share OFT bridge.
  /// @dev The share OFT reports and enforces amounts in hub-local share decimals (the vault's
  ///      decimals), while route accounting works in destination raw units. `_tokenOutDecimals`
  ///      must equal the local decimals of the destination share OFT; it is remote chain state that
  ///      this contract cannot read, so the owner must source it from the peer OFT. A value below the
  ///      share OFT's shared decimals is rejected; a value above the real one cannot be detected here
  ///      and nullifies the output floor.
  function setDestination(
    address _tokenIn,
    address _composer,
    uint256 _dstChainId,
    address _tokenOut,
    uint32 _dstEid,
    uint8 _tokenOutDecimals,
    bytes calldata _extraOptions
  ) external onlyOwner {
    if (_tokenIn == address(0) || _composer == address(0)) {
      revert ZeroAddress();
    }
    if (_dstChainId == 0 || _dstEid == 0) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (_tokenOut == address(0)) {
      revert ZeroAddress();
    }
    if (_extraOptions.length == 0) {
      revert InvalidOptions();
    }

    IOVaultComposerSync composer = IOVaultComposerSync(_composer);
    address localToken = composer.ASSET_ERC20();
    if (localToken != _tokenIn) {
      revert InvalidBridgeToken(_tokenIn, localToken);
    }
    if (composer.SHARE_OFT() == address(0) || address(composer.VAULT()) == address(0)) {
      revert ZeroAddress();
    }

    ILayerZeroOft shareOft = ILayerZeroOft(composer.SHARE_OFT());
    uint8 sharedDecimals = shareOft.sharedDecimals();
    if (_tokenOutDecimals < sharedDecimals) {
      revert InvalidTokenOutDecimals(_tokenOutDecimals, sharedDecimals);
    }

    uint8 shareDecimals = composer.VAULT().decimals();
    destinations[_tokenIn][_dstChainId] = Destination({
      composer: _composer,
      tokenOut: _tokenOut,
      dstEid: _dstEid,
      shareDecimals: shareDecimals,
      tokenOutDecimals: _tokenOutDecimals,
      shareConversionRate: shareOft.decimalConversionRate(),
      extraOptions: _extraOptions
    });
    _setBridgeRoute(_tokenIn, _tokenOut, _dstChainId);

    emit DestinationSet(
      _tokenIn, _dstChainId, _tokenOut, _composer, _dstEid, shareDecimals, _tokenOutDecimals, _extraOptions
    );
  }

  /// @notice Clears destination metadata for a destination chain.
  function clearDestination(address _tokenIn, uint256 _dstChainId) external onlyOwner {
    delete destinations[_tokenIn][_dstChainId];
    _clearBridgeRoute(_tokenIn, _dstChainId);

    emit DestinationCleared(_tokenIn, _dstChainId);
  }

  /// @notice Quotes an OVault deposit and share OFT bridge for an explicit non-zero input amount.
  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external view override returns (BridgeQuote memory _quote) {
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    return _quoteOVault(address(this), destination, _amountIn, _minAmountOut, _recipient).bridgeQuote;
  }

  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external override returns (BridgeExecution memory _execution) {
    Destination storage destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    uint256 amountIn = _resolveAmountIn(_amountIn, _inboxAssetBalance(_inbox, _tokenIn));
    OVaultQuote memory ovaultQuote = _quoteOVault(_inbox, destination, amountIn, _minAmountOut, _recipient);

    _execution.operationId = _nextOperationId(
      _inbox, _tokenIn, _tokenOut, _minAmountOut, _dstChainId, ovaultQuote.sendParam.to, ovaultQuote.fee.nativeFee
    );
    _execution.quote = ovaultQuote.bridgeQuote;

    _setInboxTokenApproval(_inbox, _tokenIn, address(ovaultQuote.composer), ovaultQuote.bridgeQuote.amountIn);
    _depositAndSend(
      ovaultQuote.composer, _inbox, ovaultQuote.bridgeQuote.amountIn, ovaultQuote.sendParam, ovaultQuote.fee.nativeFee
    );
    _setInboxTokenApproval(_inbox, _tokenIn, address(ovaultQuote.composer), 0);

    TransferReceipt memory receipt = TransferReceipt({
      amountIn: ovaultQuote.bridgeQuote.amountIn,
      amountOut: ovaultQuote.bridgeQuote.amountOut,
      nativeFee: ovaultQuote.fee.nativeFee,
      dstEid: ovaultQuote.sendParam.dstEid,
      recipient: ovaultQuote.sendParam.to
    });

    emit OVaultDepositAndBridgeStarted(
      _execution.operationId,
      _inbox,
      _tokenIn,
      _tokenOut,
      receipt.amountIn,
      receipt.amountOut,
      _minAmountOut,
      _dstChainId,
      receipt.recipient,
      receipt.nativeFee,
      receipt.dstEid
    );
  }

  function _validatedDestination(address _tokenIn, address _tokenOut, uint256 _dstChainId, bytes32 _recipient)
    private
    view
    returns (Destination storage destination)
  {
    destination = destinations[_tokenIn][_dstChainId];
    if (destination.composer == address(0)) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (_tokenOut != destination.tokenOut) {
      revert InvalidTokenOut(destination.tokenOut, _tokenOut);
    }
    if (_recipient == bytes32(0)) {
      revert InvalidRecipient();
    }
  }

  function _quoteOVault(
    address _inbox,
    Destination storage _destination,
    uint256 _amountIn,
    uint256 _minAmountOut,
    bytes32 _recipient
  ) internal view returns (OVaultQuote memory _quote) {
    if (_minAmountOut == 0) {
      revert InvalidAmount();
    }

    if (_amountIn == 0) {
      revert InvalidAmount();
    }

    IOVaultComposerSync composer = IOVaultComposerSync(_destination.composer);
    uint256 shareAmount = composer.VAULT().previewDeposit(_amountIn);
    // The share OFT drops dust below its shared decimals before sending, so only the floored amount arrives.
    uint256 sharesSent = shareAmount / _destination.shareConversionRate * _destination.shareConversionRate;
    uint256 amountOut = TokenDecimals.toRemote(sharesSent, _destination.shareDecimals, _destination.tokenOutDecimals);
    if (amountOut < _minAmountOut) {
      revert InsufficientAmountOut(_minAmountOut, amountOut);
    }

    LayerZeroSendParam memory sendParam = LayerZeroSendParam({
      dstEid: _destination.dstEid,
      to: _recipient,
      amountLD: shareAmount,
      minAmountLD: TokenDecimals.toLocalCeil(_minAmountOut, _destination.shareDecimals, _destination.tokenOutDecimals),
      extraOptions: _destination.extraOptions,
      composeMsg: "",
      oftCmd: ""
    });

    LayerZeroMessagingFee memory fee = composer.quoteSend(_inbox, composer.SHARE_OFT(), _amountIn, sendParam);

    BridgeFee[] memory fees = new BridgeFee[](1);
    fees[0] = BridgeFee({token: address(0), amount: fee.nativeFee});

    _quote = OVaultQuote({
      bridgeQuote: BridgeQuote({amountIn: _amountIn, amountOut: amountOut, fees: fees}),
      composer: composer,
      sendParam: sendParam,
      fee: fee
    });
  }

  function _depositAndSend(
    IOVaultComposerSync _composer,
    address _inbox,
    uint256 _assetAmount,
    LayerZeroSendParam memory _sendParam,
    uint256 _nativeFee
  ) internal {
    _executeInboxTransaction(
      _inbox,
      address(_composer),
      _nativeFee,
      abi.encodeCall(IOVaultComposerSync.depositAndSend, (_assetAmount, _sendParam, _inbox))
    );
  }

  function _nextOperationId(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    uint256 _nativeFee
  ) internal returns (bytes32) {
    uint256 nonce = nextOperationNonce++;
    return keccak256(
      abi.encode(
        block.chainid,
        address(this),
        nonce,
        msg.sender,
        _inbox,
        _tokenIn,
        _tokenOut,
        _minAmountOut,
        _dstChainId,
        _recipient,
        _nativeFee
      )
    );
  }
}

