struct LayerZeroOftFeeDetail {
  int256 feeAmountLD;
  string description;
}

/// @notice LayerZero messaging fee
struct LayerZeroMessagingFee {
  uint256 nativeFee;
  uint256 lzTokenFee;
}

/// @notice LayerZero messaging receipt
struct LayerZeroMessagingReceipt {
  bytes32 guid;
  uint64 nonce;
  LayerZeroMessagingFee fee;
}

/// @title ILayerZeroOft
/// @author Agustin Aguilar
/// @notice Minimal LayerZero OFT interface
interface ILayerZeroOft {
  function token() external view returns (address);

  function approvalRequired() external view returns (bool);

  function sharedDecimals() external view returns (uint8);

  function decimalConversionRate() external view returns (uint256);

  function quoteOFT(LayerZeroSendParam calldata _sendParam)
    external
    view
    returns (
      LayerZeroOftLimit memory _limit,
      LayerZeroOftFeeDetail[] memory _oftFeeDetails,
      LayerZeroOftReceipt memory _receipt
    );

  function quoteSend(LayerZeroSendParam calldata _sendParam, bool _payInLzToken)
    external
    view
    returns (LayerZeroMessagingFee memory _fee);

  function send(LayerZeroSendParam calldata _sendParam, LayerZeroMessagingFee calldata _fee, address _refundAddress)
    external
    payable
    returns (LayerZeroMessagingReceipt memory _msgReceipt, LayerZeroOftReceipt memory _oftReceipt);
}

