// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title TokenDecimals
/// @notice Conversions between a bridge's source-local and destination-local token denominations
/// @dev LayerZero OFTs (and Stargate, which is built on them) report `amountReceivedLD` and
///      interpret `minAmountLD` in SOURCE local decimals; the destination credits the same value in
///      its own local decimals. Route accounting compares `BridgeQuote.amountOut` and the executor's
///      `_minAmountOut` with an oracle minimum expressed in DESTINATION raw units, so adapters must
///      convert between the two. Rounding always favors the route: destination output rounds down
///      and source-local minimums round up.
library TokenDecimals {
  uint8 internal constant NATIVE_DECIMALS = 18;

  /// @notice Returns the local decimals of `_token`, or 18 for the native asset (`address(0)`).
  function localDecimals(address _token) internal view returns (uint8) {
    if (_token == address(0)) {
      return NATIVE_DECIMALS;
    }

    return IERC20Metadata(_token).decimals();
  }

  /// @notice Converts a source-local amount into destination-local units, rounding down.
  function toRemote(uint256 _amountLocal, uint8 _localDecimals, uint8 _remoteDecimals) internal pure returns (uint256) {
    if (_localDecimals == _remoteDecimals) {
      return _amountLocal;
    }
    if (_localDecimals > _remoteDecimals) {
      return _amountLocal / 10 ** (_localDecimals - _remoteDecimals);
    }

    return _amountLocal * 10 ** (_remoteDecimals - _localDecimals);
  }

  /// @notice Converts a destination-local amount into source-local units, rounding up.
  function toLocalCeil(uint256 _amountRemote, uint8 _localDecimals, uint8 _remoteDecimals)
    internal
    pure
    returns (uint256)
  {
    if (_localDecimals == _remoteDecimals) {
      return _amountRemote;
    }
    if (_localDecimals > _remoteDecimals) {
      return _amountRemote * 10 ** (_localDecimals - _remoteDecimals);
    }

    return Math.ceilDiv(_amountRemote, 10 ** (_remoteDecimals - _localDecimals));
  }
}

